/* Listen to this page: natural-voice narration generated by /api/narrate */
(function () {
  "use strict";
  var $ = function (sel, root) { return (root || document).querySelector(sel); };
    var h1 = $("main h1");
    if (!h1 || !window.Audio) return;
    var pagePath = location.pathname.replace(/\.html$/, "").replace(/\/$/, "") || "/";
    if (pagePath === "/index") pagePath = "/";
    var playIcon = '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path fill="currentColor" d="M8 5.5v13a1 1 0 0 0 1.5.86l10.5-6.5a1 1 0 0 0 0-1.72L9.5 4.64A1 1 0 0 0 8 5.5z"/></svg>';
    var pauseIcon = '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path fill="currentColor" d="M7 5h3.5v14H7zM13.5 5H17v14h-3.5z"/></svg>';
    var speeds = [1, 1.25, 0.85];

    var box = document.createElement("div");
    box.className = "narrate";
    box.innerHTML =
      '<button type="button" class="narrate-play" aria-pressed="false">' + playIcon + '<span class="narrate-label">Listen to this page</span></button>' +
      '<button type="button" class="narrate-speed" aria-label="Narration speed, 1 times" hidden>1x</button>' +
      '<button type="button" class="narrate-stop" hidden>Stop</button>' +
      '<span class="narrate-status" role="status" aria-live="polite"></span>';
    h1.insertAdjacentElement("afterend", box);

    var playBtn = $(".narrate-play", box), label = $(".narrate-label", box);
    var speedBtn = $(".narrate-speed", box), stopBtn = $(".narrate-stop", box), status = $(".narrate-status", box);
    var manifest = null, part = 0, speedIdx = 0, current = null, next = null, playing = false;

    function src(i) { return "/api/narrate?path=" + encodeURIComponent(pagePath) + "&part=" + i + "&v=" + manifest.version; }
    function makeAudio(i) {
      var a = new Audio(); a.preload = "auto"; a.src = src(i); a.playbackRate = speeds[speedIdx];
      a.addEventListener("ended", function () { if (a === current) advance(); });
      a.addEventListener("error", function () { if (a === current) fail(); });
      a.addEventListener("waiting", function () { if (a === current) say("Loading…"); });
      a.addEventListener("playing", function () { if (a === current) progress(); });
      return a;
    }
    function say(t) { status.textContent = t; }
    function progress() { say(manifest.parts > 1 ? "Part " + (part + 1) + " of " + manifest.parts : ""); }
    function setPlaying(on) {
      playing = on;
      playBtn.setAttribute("aria-pressed", String(on));
      playBtn.firstChild.outerHTML = on ? pauseIcon : playIcon;
      label.textContent = on ? "Pause" : (current ? "Resume" : "Listen to this page");
      speedBtn.hidden = stopBtn.hidden = !current;
    }
    function start(i) {
      var prefetched = next && next.dataset.part === String(i) ? next : null;
      part = i;
      current = prefetched || makeAudio(i);
      next = part + 1 < manifest.parts ? makeAudio(part + 1) : null;
      if (next) next.dataset.part = String(part + 1);
      current.playbackRate = speeds[speedIdx];
      setPlaying(true);
      var p = current.play();
      if (p && p.catch) p.catch(function () { if (current) { setPlaying(false); say("Press play to continue."); } });
    }
    function advance() {
      if (part + 1 < manifest.parts) { start(part + 1); return; }
      reset(); say("Finished.");
    }
    function reset() {
      if (current) current.pause();
      if (next) next.src = "";
      current = next = null; part = 0;
      setPlaying(false);
      say("");
    }
    function fail() { reset(); say("Narration is unavailable right now. Please try again later."); }

    playBtn.addEventListener("click", function () {
      if (playing) { current.pause(); setPlaying(false); say("Paused."); return; }
      if (current) { current.play(); setPlaying(true); progress(); return; }
      if (manifest) { start(0); return; }
      playBtn.disabled = true; say("Preparing narration…");
      fetch("/api/narrate?path=" + encodeURIComponent(pagePath))
        .then(function (r) { if (!r.ok) throw new Error(); return r.json(); })
        .then(function (m) { manifest = m; playBtn.disabled = false; start(0); })
        .catch(function () { playBtn.disabled = false; fail(); });
    });
    stopBtn.addEventListener("click", function () { reset(); playBtn.focus(); });
    speedBtn.addEventListener("click", function () {
      speedIdx = (speedIdx + 1) % speeds.length;
      var s = speeds[speedIdx];
      speedBtn.textContent = s + "x";
      speedBtn.setAttribute("aria-label", "Narration speed, " + s + " times");
      if (current) current.playbackRate = s;
      if (next) next.playbackRate = s;
    });
  })();
